mapper.select:

where si.del_flag = '0'

    and si.stock_in_id like concat('%', #{query.stockInId}, '%')


    and si.warehouse_id = #{query.warehouseId}


    and si.supplier_id = #{query.supplierId}


    and si.type = #{query.type}


    and si.status = #{query.status}


    and si.batch_no like concat('%', #{query.batchNo}, '%')


    and si.create_time >= #{query.createTimeStart}


    and si.create_time <= #{query.createTimeEnd}

order by si.create_time desc
